      await waitFor(() => expect(checkbox).toBeEnabled())
      expectStored()
      expect(toastError).toHaveBeenCalledTimes(1)
      expect(toastSuccess).not.toHaveBeenCalled()
    }
  )

  it('e. a failed toggle with no error text falls back to the fixed wording', async () => {
